script:
const CFG = {"asked": "aorta", "level": "T12", "open": "Aortic opening"};
const el = {};
function bez(p, t) { const u = 1 - t; return [u*u*u*p[0][0]+3*u*u*t*p[1][0]+3*u*t*t*p[2][0]+t*t*t*p[3][0], u*u*u*p[0][1]+3*u*u*t*p[1][1]+3*u*t*t*p[2][1]+t*t*t*p[3][1]]; }
function xAtY(p, y) { let a = 0, b = 1; for (let i = 0; i < 40; i++) { const m = (a + b) / 2; if (bez(p, m)[1] < y) a = m; else b = m; } return bez(p, a)[0]; }
const RC = [[250,240],[340,240],[430,340],[505,462]];
const LC = [[52,462],[100,340],[170,240],[250,240]];
const VY = {T7:196, T8:240, T9:284, T10:328, T11:372, T12:416, L1:460};
const GREY = "#7b8a90", RED = "#c0392b";
const KIND = {ivc: ["vein","#2b4f9e","Vena cava","#e3ecff"], oes: ["gut","#a8505a","Oesophagus","#fff3d6"], aorta: ["artery","#a5232b","Aorta","#ffe9e6"], duct: [null,"#8a6d00","Thoracic duct","#fff6cf"]};
function setup(api) {
  const P = api.svg;
  const xI = 250, xO = xAtY(RC, VY.T10), xA = xAtY(RC, VY.T12), xD = xA + 24;
  el.X = {ivc: xI, oes: xO, aorta: xA, duct: xD};
  // vertebral column
  el.vb = {};
  Object.keys(VY).forEach((n) => { const y = VY[n], g = api.el("g", {}, P);
    api.el("rect", {x: 578, y: y - 7, width: 22, height: 14, rx: 7, fill: "#e6d9bb", stroke: "#b9a47a", "stroke-width": 1.5}, g);
    g.hot = api.el("rect", {x: 520, y: y - 18, width: 58, height: 36, rx: 12, fill: "#ffd966", stroke: "#e0a800", "stroke-width": 3, opacity: 0}, g);
    g.base = api.el("rect", {x: 520, y: y - 18, width: 58, height: 36, rx: 12, fill: "url(#kit-bone)", stroke: "#b9a47a", "stroke-width": 2}, g);
    g.insertBefore(g.base, g.hot); g.hot.parentNode.appendChild(g.hot); g.hot.setAttribute("fill-opacity", 0.55);
    R.text(api, g, n, 549, y + 6, {size: 16, anchor: "middle", color: "#7a6a45", halo: false});
    el.vb[n] = g; });
  // diaphragm band
  const dd = `M${LC[0]} C${LC[1]} ${LC[2]} ${LC[3]} C${RC[1]} ${RC[2]} ${RC[3]}`.replace(/,/g, " ");
  api.el("path", {d: dd, fill: "none", stroke: "#8e2a27", "stroke-width": 30, "stroke-linecap": "round", filter: "url(#kit-shadow)"}, P);
  api.el("path", {d: dd, fill: "none", stroke: "url(#kit-muscle)", "stroke-width": 24, "stroke-linecap": "round"}, P);
  api.el("path", {d: dd, fill: "none", stroke: "#fff", "stroke-width": 3, "stroke-opacity": 0.28, "stroke-linecap": "round", transform: "translate(0 -5)"}, P);
  // openings (holes)
  const open = [["ivc", xI, VY.T8, 20], ["oes", xO, VY.T10, 20], ["aorta", xA + (CFG.asked === "duct" ? 11 : 0), VY.T12, CFG.asked === "duct" ? 31 : 20]];
  el.ring = {};
  open.forEach(([k, x, y, rx]) => { el["h_" + k] = api.el("ellipse", {cx: x.toFixed(1), cy: y, rx, ry: 12, fill: "#fff", stroke: "#8e2a27", "stroke-width": 3}, P);
    el.ring[k] = api.el("ellipse", {cx: x.toFixed(1), cy: y, rx: rx + 3, ry: 15, fill: "none", stroke: RED, "stroke-width": 5, opacity: 0, filter: "url(#kit-glow)"}, P); });
  // structures
  const pth = {ivc: `M${xI} 340 L${xI} 198`, oes: `M${xO} 198 L${xO} 404`, aorta: `M${xA} 198 L${xA} 514`, duct: `M${xD} 470 L${xD} 198`};
  const wd = {ivc: 26, oes: 22, aorta: 26, duct: 7};
  el.tube = {}; el.flow = {};
  ["ivc", "oes", "aorta", "duct"].forEach((k) => {
    if (k === "duct" && CFG.asked !== "duct") return;
    const K = KIND[k];
    if (k === "oes") { const g = api.el("g", {}, P); api.el("path", {d: pth[k], fill: "none", stroke: "#8a3a44", "stroke-width": 25, "stroke-linecap": "round"}, g);
      g.p = api.el("path", {d: pth[k], fill: "none", stroke: "#e58b95", "stroke-width": 21, "stroke-linecap": "round"}, g); el.tube[k] = g; }
    else if (K[0]) el.tube[k] = R.tube(api, P, pth[k], K[0], wd[k]);
    else { const g = api.el("g", {}, P); api.el("path", {d: pth[k], fill: "none", stroke: "#8a6d00", "stroke-width": 10, "stroke-linecap": "round"}, g);
      g.p = api.el("path", {d: pth[k], fill: "none", stroke: "#f2cf5b", "stroke-width": 7, "stroke-linecap": "round"}, g); el.tube[k] = g; }
    el.tube[k].setAttribute("opacity", 0);
    el.flow[k] = R.flow(api, P, el.tube[k].p, {n: 4, color: K[3], period: 1500, r: k === "duct" ? 2.5 : 3.5});
  });
  // level line + answer
  const vy = VY[CFG.level], ox = open[CFG.asked === "ivc" ? 0 : CFG.asked === "oes" ? 1 : 2][1];
  el.lvl = api.el("path", {d: "M0 0", fill: "none", stroke: RED, "stroke-width": 4, "stroke-dasharray": "9 6", "stroke-linecap": "round", opacity: 0}, P);
  el.lvlA = [ox + (CFG.asked === "duct" ? 36 : 22), 520, vy];
  // labels
  const nameY = 172;
  el.names = {};
  ["ivc", "oes", "aorta", "duct"].forEach((k) => { if (k === "duct" && CFG.asked !== "duct") return;
    const K = KIND[k], x = el.X[k], hot = k === CFG.asked, col = hot ? K[1] : GREY;
    const cy = k === "duct" ? 148 : nameY, cx = k === "duct" ? 540 : k === "oes" ? x - 45 : k === "aorta" ? x + 25 : x;
    el.names[k] = R.callout(api, P, K[2], cx, cy, col, [x, k === "duct" ? 204 : 200], null); });
  el.nm = Object.keys(el.names).map(k => k);
  el.dia = R.callout(api, P, "Diaphragm", 120, 330, "#8e2a27", bez(LC, 0.3), null);
  el.ans = [R.chip(api, P, CFG.level, 78, 172, RED, {size: 34, anchor: "middle"})];
  el.ans2 = R.chip(api, P, CFG.open, 48, 218, RED, {size: 17});
}
function render(t, api) {
  const k = CFG.asked, f01 = (a, b) => api.seg(t, a, b);
  // beat 1: holes + diaphragm label
  R.fade(api, el.dia, t, 300, 800, 2000, 2300);
  // beat 2: structures appear, asked one lights up
  Object.keys(el.tube).forEach((n) => {
    const hot = n === k, grow = f01(2350, hot ? 3500 : 2900);
    R.drawOn(api, el.tube[n], grow);
    const dim = hot ? 1 : (n === "duct" ? 0.3 : 0.3);
    api.set(el.tube[n], {opacity: (f01(2350, 2450) * (hot ? 1 : 0.32)).toFixed(3)});
    el.flow[n].update(t, hot ? f01(3400, 3800) : 0);
  });
  Object.keys(el.names).forEach((n) => R.fade(api, el.names[n], t, n === k ? 3000 : 3300, n === k ? 3400 : 3700));
  const pulse = 0.75 + 0.25 * Math.sin(t / 220);
  const ringN = k === "duct" ? "aorta" : k;
  api.set(el.ring[ringN], {opacity: (f01(3000, 3500) * (t > 4600 ? 1 : pulse)).toFixed(3)});
  // beat 3: level
  const g = api.ease("ease_in_out", f01(4700, 5500));
  const [x0, x1, y] = el.lvlA;
  api.set(el.lvl, {d: `M${x0} ${y}L${(x0 + (x1 - x0) * g).toFixed(1)} ${y}`, opacity: f01(4700, 4800).toFixed(3)});
  api.set(el.vb[CFG.level].hot, {opacity: f01(5300, 5800).toFixed(3)});
  R.fade(api, el.ans, t, 5500, 5950);
  R.fade(api, el.ans2, t, 5700, 6150);
}
